func (q *Queries) ListWhatsAppThreadsDetailedByScheme(ctx context.Context, schemeID uuid.UUID) ([]ListWhatsAppThreadsDetailedBySchemeRow, error) {
	rows, err := q.db.Query(ctx, listWhatsAppThreadsDetailedByScheme, schemeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWhatsAppThreadsDetailedBySchemeRow{}
	for rows.Next() {
		var i ListWhatsAppThreadsDetailedBySchemeRow
		if err := rows.Scan(
			&i.ID,
			&i.SchemeID,
			&i.UnitID,
			&i.ResidentUserID,
			&i.PhoneNumber,
			&i.Connected,
			&i.ConsentedAt,
			&i.UnreadCount,
			&i.LastActiveAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.UnitIdentifier,
			&i.OwnerName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

